# Script to fit SPR affinity data
# Works with *SteadyState.txt files
# Ex: python ~/RESEARCH/SCRIPTS/spr_AffinityFit4FA.py -Rmin=0.01 -mc=100 -noise=5. -norm=1

import sys,os,re,argparse,math
from random import gauss
from scipy import optimize as o
import numpy as np
import matplotlib.pylab as plt
import matplotlib.ticker as plticker


def LoadData(file,norm):
    FILE = open(file, 'r')
    all_lines = FILE.readlines()
    #print(all_lines)
    X = []; Y = []; N = []
    for line in all_lines[1:]:
        #line=line.replace(',','.')
        #print line
        #linesplit=line.split("\t")
        linesplit = re.split(r'\s+', line)
        print(linesplit)
        if (linesplit[0]):
            X.append(float(linesplit[0])*1e-6)
            Y.append(float(linesplit[1]))
            if (norm == 1):
                #print(linesplit, len(linesplit))
                if (len(linesplit) != 5):
                    print("Data file must contained peptide immobilization level in the 3rd column")
                else:
                    N.append(float(linesplit[2]))
    X=np.array(X)
    Y=np.array(Y)
    print(X)
    print(Y)
    MeanImmob = 1.
    if (norm == 1):
        N=np.array(N)
        MeanImmob = np.mean(N)
        print(N)
        Y=Y/N
    return(X,Y,MeanImmob)

def FitFit(X,Y,fun):
    residuals = lambda PAR, X, Y, fun: Y - COMPLEX(X, PAR)    
    (v, cov_v) = o.leastsq(residuals, PAR, args=(X, Y, COMPLEX))
    #print(v, cov_v)
    return v

def FitFitRM(X,Y,fun):
    residuals = lambda PAR, X, Rmax, Y, fun: Y - COMPLEX(X, Rmax, PAR)    
    (v, cov_v) = o.leastsq(residuals, PAR, args=(X, Rmax, Y, COMPLEX))
    #print(v, cov_v)
    return v

def FitFitRm(X,Y,fun):
    residuals = lambda PAR, X, Rmin, Y, fun: Y - COMPLEX(X, Rmin, PAR)    
    (v, cov_v) = o.leastsq(residuals, PAR, args=(X, Rmin, Y, COMPLEX))
    #print(v, cov_v)
    return v

def Noiser(Val, Noise):
    Data = []
    for val in Val: Data.append(gauss(val, Noise))
    Data = np.array(Data)
    return Data
 

